MODELAGEM_LOGICO_ALGORITMA.CODIGO_FONTE:
if (dist < 100) {
  pos = 90;
  myservo.write(pos);
  digitalWrite(ledPin, HIGH);
  tone(buzzerPin, 1200);
  delay(150);
  digitalWrite(ledPin, LOW);
  noTone(buzzerPin);
  delay(150);
} else {
  pos = 0;
  myservo.write(pos);
  digitalWrite(ledPin, LOW);
  noTone(buzzerPin);
  delay(15);
}
